// Package cmdsuggest renders the command-suggestion list shown under the
// command line (DEVDESK-89). Rendering is pure: state in, lines out.
package cmdsuggest

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/lipgloss"
	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// MaxVisibleRows is the ceiling on suggestion rows shown at once.
const MaxVisibleRows = 8

// Row is one suggestion; Current marks the view that is open now.
type Row struct {
	Entry   command.Entry
	Current bool
}

// Frame selects the corners of the bottom rule.
type Frame int

const (
	// FrameJoined draws ├─┤ (the list sits above more viewport content).
	FrameJoined Frame = iota
	// FrameClosed draws └─┘.
	FrameClosed
)

// Input is everything Render needs.
type Input struct {
	Rows    []Row
	Total   int
	Query   string
	Cursor  int // -1 means no highlighted row
	Offset  int
	Notice  string
	Width   int
	Visible int
	Frame   Frame
}

// Layout holds column widths in cells.
type Layout struct{ Marker, Name, Alias, Desc int }

// Pair is a foreground/background combination the list paints.
type Pair struct {
	Name   string
	Fg, Bg lipgloss.Color
}

// Layout constants, in cells. The widths below are the whole grid: a line is
// a border, a one-cell margin, the columns, then fill up to the other border.
const (
	margin        = 1
	markerWidth   = 2
	minDescWidth  = 20
	minAliasWidth = 34 // narrowest terminal that still shows the alias column
	wideWidth     = 100
	aliasSep      = " · "
	currentTag    = "(current)"
	ellipsis      = "…"
	// minRenderWidth is the narrowest width that holds a frame, a margin, a
	// marker and one name cell.
	minRenderWidth = 6
)

// VisibleRows returns how many list rows fit: the matches, at least one row
// (the "no match" line), capped by MaxVisibleRows and by the usable height
// minus the filet.
func VisibleRows(matches, usable int) int {
	return max(min(max(matches, 1), MaxVisibleRows, usable-1), 0)
}

// Window returns the first visible row so that cursor stays in view. The
// window never wraps and, with no highlighted row, keeps the current offset.
func Window(cursor, offset, visible int) int {
	offset = max(offset, 0)
	if cursor < 0 || visible <= 0 {
		return offset
	}
	switch {
	case cursor < offset:
		return cursor
	case cursor >= offset+visible:
		return cursor - visible + 1
	}
	return offset
}

// Columns returns the column widths for a terminal width. Columns leave from
// the right: description first, then alias; the name alone remains.
func Columns(width int) Layout {
	l := Layout{Marker: markerWidth}
	if width < minAliasWidth {
		l.Name = max(width-6, 1)
		return l
	}
	l.Name, l.Alias = 15, 14
	if width >= wideWidth {
		l.Name, l.Alias = 18, 18
	}
	if desc := width - 2 - margin - l.Marker - l.Name - l.Alias; desc >= minDescWidth {
		l.Desc = desc
	}
	return l
}

// first returns the index of the first row drawn, kept inside the list.
func first(in Input) int {
	return max(min(in.Offset, len(in.Rows)-max(in.Visible, 0)), 0)
}

// FiletLabel returns the text of the bottom rule: the notice as a warning
// when there is one, otherwise the count with what scrolled out of view.
func FiletLabel(in Input) string {
	if in.Notice != "" {
		return theme.IconWarning + " " + in.Notice
	}
	in.Visible = max(in.Visible, 0)
	label := fmt.Sprintf("%d of %d", len(in.Rows), in.Total)
	if strings.TrimSpace(in.Query) == "" {
		label = fmt.Sprintf("%d available", len(in.Rows))
	}
	start := first(in)
	if above := start; above > 0 {
		label += fmt.Sprintf(" · ▲ %d more", above)
	}
	if below := len(in.Rows) - start - in.Visible; below > 0 {
		label += fmt.Sprintf(" · ▼ %d more", below)
	}
	return label
}

// look is one foreground/background combination, read from the theme at call
// Render returns Visible list rows followed by the bottom rule, each exactly
// Width cells wide. Every line is assembled from separately styled segments;
// no already-styled text is ever cut.
func Render(in Input) []string {
	in.Visible = max(in.Visible, 0)
	if in.Width < minRenderWidth {
		return degenerate(in)
	}
	inner := max(in.Width-2, 0)
	layout := Columns(in.Width)
	border := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)
	side := border.Render("│")

	lines := make([]string, 0, in.Visible+1)
	if len(in.Rows) == 0 {
		for i := 0; i < in.Visible; i++ {
			body := theme.EmptyLineBg(inner)
			if i == 0 {
				body = row(noMatchText(in.Query), layout, inner, false)
			}
			lines = append(lines, side+body+side)
		}
	} else {
		start := first(in)
		for i := 0; i < in.Visible; i++ {
			idx := start + i
			if idx >= len(in.Rows) {
				lines = append(lines, side+theme.EmptyLineBg(inner)+side)
				continue
			}
			lines = append(lines, side+row(columnsOf(in.Rows[idx], layout), layout, inner, idx == in.Cursor)+side)
		}
	}
	return append(lines, filet(in, inner, border))
}

// degenerate renders the lines of a terminal too narrow for a frame: blank
// background lines and a bare rule, each exactly Width cells (possibly zero).
func degenerate(in Input) []string {
	w := max(in.Width, 0)
	lines := make([]string, 0, in.Visible+1)
	for i := 0; i < in.Visible; i++ {
		lines = append(lines, theme.EmptyLineBg(w))
	}
	rule := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)
	return append(lines, rule.Render(strings.Repeat("─", w)))
}

// cells is the plain text of each column of one row.
// A message spans every column.
type cells struct{ name, alias, desc, message string }
package app

import (
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// View renders the interface: header, title line, viewport, footer (Rule 124).
// An open overlay replaces the whole thing.
func (a *App) View() string {
	if overlay := a.activeOverlay(); overlay != "" {
		return lipgloss.Place(a.width, a.height, lipgloss.Center, lipgloss.Center, overlay,
			lipgloss.WithWhitespaceBackground(theme.ColorBackground))
	}

	inner := a.renderHeader() + "\n" + a.renderTitleLine() + "\n" + a.renderBody()
	if footer := a.renderViewFooter(); footer != "" {
		inner += "\n" + footer
	}

	return lipgloss.Place(a.width, a.height, lipgloss.Left, lipgloss.Top, inner,
		lipgloss.WithWhitespaceBackground(theme.ColorBackground))
}

// activeOverlay returns the overlay to draw instead of the view, or "" when
// there is none. The order matches the one handleKeyMsg dispatches in, so the
// overlay holding the keyboard is the one on screen.
func (a *App) activeOverlay() string {
	switch {
	case a.switchingTo != "":
		return a.renderContextSwitchingOverlay()
	case a.showHelp:
		return a.renderHelpOverlay()
	case a.showContextList:
		return a.renderContextListOverlay()
	}
	return ""
}

// renderBody fills the viewport with the active view's content, padded to the
// full inner width so no line shows the terminal's own background (Rule 115).
func (a *App) renderBody() string {
	content := "View not found: " + string(a.currentView)
	if view, ok := a.views[a.currentView]; ok {
		content = view.View()
	}

	innerWidth := a.viewport.Width - 2 // -2 for the borders
	if a.frameless() {
		innerWidth = a.viewport.Width
	}
	a.viewport.SetContent(lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorText).
		Width(innerWidth).
		Render(content))

	body := a.viewport.View()

	// Rule 136: with a filter bar below it, the viewport's bottom corners become
	// T-junctions so the two form one closed rectangle.
	if view, ok := a.views[a.currentView]; ok {
		if fbv, ok := view.(FilterBarView); ok && fbv.FilterBarVisible() {
			body = replaceViewportBottomCorners(body)
		}
	}
	return body
}

// renderTitleLine draws the viewport's top border carrying the view's title —
// or, for a frameless view, a titled rule with no corners: GetTitle() keeps a
// reader oriented where a top border would draw the top of a nonexistent box.
func (a *App) renderTitleLine() string {
	title := ""
	if view, ok := a.views[a.currentView]; ok {
		if hv, implements := view.(HeaderView); implements {
			title = hv.GetTitle()
		}
	}
	if a.frameless() {
		return theme.RenderTitledRule(title, a.width)
	}
	return theme.RenderBorderTitle(title, a.width)
}

// frameless reports whether the active view draws its own frames (see
// FramelessView). The default is framed.
func (a *App) frameless() bool {
	view, ok := a.views[a.currentView]
	if !ok {
		return false
	}
	fv, implements := view.(FramelessView)
	return implements && fv.Frameless()
}

// renderViewFooter returns the active view's footer, or "" when it has none.
func (a *App) renderViewFooter() string {
	if view, ok := a.views[a.currentView]; ok {
		if fv, ok := view.(FooterView); ok {
			return fv.RenderFooter(a.width)
		}
	}
	return ""
}

// replaceViewportBottomCorners turns the viewport's bottom └ and ┘ into the
// T-junctions ├ and ┤, so the filter bar rendered below it in the footer joins
// the border into one closed rectangle instead of two stacked boxes.
func replaceViewportBottomCorners(body string) string {
	lastNewline := strings.LastIndex(body, "\n")
	if lastNewline == -1 {
		return body
	}
	lastLine := body[lastNewline+1:]
	lastLine = strings.Replace(lastLine, "└", "├", 1)
	lastLine = strings.Replace(lastLine, "┘", "┤", 1)
	return body[:lastNewline+1] + lastLine
}
package app

import (
