type FilterBarView interface {
	FilterBarVisible() bool
}

// App is the main model, with a multi-view router
type App struct {
	config         *config.Config
	currentContext string
	viewport       viewport.Model

	// Navigation
	currentView command.ViewType
	views       map[command.ViewType]tea.Model
	sharedState *shared.State

	commandMode  bool
	commandInput textinput.Model

	// View picker: Tab in the command line swaps it for a circular breadcrumb
	// of every view. The typed text is kept underneath.
	viewPicker      bool
	viewPickerViews []string
	viewPickerIdx   int

	// Command completion state
	completionEngine      *command.CompletionEngine
	completionSuggestions []command.Suggestion
	completionIndex       int    // Highlighted suggestion (always the first one)
	completionInput       string // Change detection

	// Context list overlay
	showContextList    bool
	contextList        []string
	contextSelectedIdx int
	// switchingTo names the context a switch is loading, or "" when none is.
	// While it is set the previous context's interface is not drawn: the load
	// includes a network login, and showing the old views for its duration
	// read as the new context appearing first and switching afterwards.
	switchingTo string

	// Help overlay
	wantedProxyPort atomic.Int64
	// pendingInvocations holds the reply channel of every action call waiting
	// for the identifier of the run it asked for. Mutated from Update alone,
	// like everything else here.
	pendingInvocations map[invocationID]chan mcpStartReply
	mcpAddr            string
	mcpErr             error

	// Dimensions
	width            int
	height           int
	lastFooterHeight int // tracks current view's footer height for re-resize detection
}

func newCommandInput() textinput.Model {
	// Create the input for command mode
	cmdInput := textinput.New()
	cmdInput.Prompt = "❯"
	cmdInput.SetSuggestions([]string{"status", "workspaces"})
	cmdInput.CharLimit = 50

	return cmdInput
}

func newViewport(width, height int) viewport.Model {
	vp := viewport.New(width, height)
		// Created here and never replaced: the forwards outlive every view
		// rebuild, and a context switch with them (§3.1).
		Forwards: forward.New(),
	}
	// Telling the registry which port is not I/O — nothing is serving yet, so
	// nothing is bound — and a route opened before the first Cmd needs to know.
	_ = sharedState.Forwards.SetProxyPort(cfg.Network.ProxyPort)

	app := &App{
		config:           cfg,
		currentContext:   currentContext,
		viewport:         newViewport(width, height),
		currentView:      defaultView(cfg),
		views:            make(map[command.ViewType]tea.Model),
		sharedState:      sharedState,
		jobs:             jobs.New(),
		commandInput:     newCommandInput(),
